    for sc in ["maintain", "revise", "doubt"]
}
mx = max(logpost.values())
post = {sc: float(np.exp(v-mx)) for sc, v in logpost.items()}
z = sum(post.values())
post = {sc: v/z for sc, v in post.items()}

print("scenario log-likelihoods:", ll)
print("scenario posterior:", post)

code = f"""
import pandas as pd, numpy as np

TARGET_LINE = {target_line}
GAIN = {float(gain)}
SCALE = {float(scale)}
AMPLITUDE = {float(amplitude)}
NOISE_BASE = {float(noise_base)}
NOISE_HIGH_SLOPE = {float(noise_high_slope)}
INITIAL_REGION_MAX = {float(initial_region_max)}
ACTIVATION_END = {float(activation_end)}
POST = {post}

def _phi(driver):
    driver = np.asarray(driver, dtype=float)
    t = (driver - INITIAL_REGION_MAX) / (ACTIVATION_END - INITIAL_REGION_MAX)
    return np.where(driver <= INITIAL_REGION_MAX, 0.0,
                    np.where(driver >= ACTIVATION_END, 1.0, t*t*(3 - 2*t)))

def _base_mean(driver):
    driver = np.asarray(driver, dtype=float)
    return 10 + GAIN * (1 - np.exp(-driver / SCALE))

def _base_sd(driver):
    driver = np.asarray(driver, dtype=float)
    return NOISE_BASE + NOISE_HIGH_SLOPE * np.maximum(driver - 5, 0)

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    driver = float(regime.config.get("driver", 0.0))
    line = int(regime.config.get("line", 0))
    mu = np.repeat(_base_mean(driver), n).astype(float)
    sd = np.repeat(_base_sd(driver), n).astype(float)
    if line == TARGET_LINE:
        scenario = rng.choice(["maintain","revise","doubt"], p=np.array([POST["maintain"], POST["revise"], POST["doubt"]], dtype=float))
        ph = float(_phi(driver))
        if scenario == "revise":
            mu = mu - AMPLITUDE * ph
        elif scenario == "doubt":
            mu = mu + rng.choice([-1.0, 1.0], size=n) * AMPLITUDE * ph
    return pd.DataFrame({{"outcome": rng.normal(mu, sd, size=n)}})
"""
env.register_model(code)
